    emit('environment',python=sys.version,executable=sys.executable,pytest=pytest.__version__,base_import=bt_api_base.__file__, tests_init_absent=True,sys_path_includes=['Base/src','Base root','Base/tests'], namespace_harness='Explicit local tests namespace; collection harness adjustment, not product behavior.', verified_test_module_origin=str(origin), audit_self_test='listed events blocked; socketpair works')
    files=['tests/test_http_retry.py','tests/test_account_protocol.py','tests/test_market_protocol.py','tests/test_market_history_protocol.py','tests/test_logging_factory_cold_start.py','tests/test_iter63_claim_fence.py','tests/test_iter63_claim_fence_coverage_seal.py','tests/containers/test_container_contract_v1.py','tests/test_thread_safety.py','tests/test_quality_batch_v4.py','tests/test_websocket_stop_lifecycle.py']
    nodes=['tests/test_service_protocol.py::test_transport_protocols_are_structural_and_service_protocol_import_is_stdlib_only','tests/test_wire_codec_v1.py::test_importing_the_contract_does_not_import_msgpack','tests/test_wire_account_codec.py::test_account_snapshot_cross_process_roundtrip','tests/test_wire_exit_gates.py::test_mixed_version_matrix_against_a_separate_old_process','tests/test_wire_strategy_commands.py::test_command_roundtrips_across_a_fresh_process']
    args=['--collect-only','-p','no:cacheprovider','-p','pytest_asyncio.plugin','--basetemp',str(tmp/'pytest-tmp'),'-q']+['--ignore='+p for p in files]+['--deselect='+n for n in nodes]+['tests']
    emit('configuration',args=args,ignored_files=files,deselected_nodes=nodes,blocked_audit_events=sorted(blocked))
    class Recorder:
        def pytest_collectstart(self,collector):
            global current_module
            name=str(getattr(collector,'nodeid','')).split('::')[0]
            if name.endswith('.py'): current_module=os.path.basename(name)
        def pytest_collection_modifyitems(self,items): emit('candidates',nodeids=[i.nodeid for i in items])
        def pytest_deselected(self,items): emit('deselected',nodeids=[i.nodeid for i in items])
        def pytest_collectreport(self,report):
            if report.failed or report.skipped: emit('collection_report',nodeid=report.nodeid,outcome=report.outcome,detail=str(report.longrepr))
        def pytest_warning_recorded(self,warning_message,when,nodeid,location): emit('warning',nodeid=nodeid,when=when,category=warning_message.category.__name__,message=str(warning_message.message),location=location)
        def pytest_runtest_logreport(self,report): emit('unexpected_phase',nodeid=report.nodeid,phase=report.when,outcome=report.outcome)
    code=int(pytest.main(args,plugins=[Recorder()]))
    emit('exit',code=code)
except BaseException as e:
    emit('exception',type=type(e).__name__,detail='Harness or safety check aborted; inspect guarded events and captured output.')
finally:
    stream.close()

